"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["19508"],{916(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.banca.tipo_nao_admite_instancia_superior","status":422,"titulo":"O recurso admite inst\xe2ncia superior, mas o item avaliado se encerra na 1\xaa inst\xe2ncia"},"descricao":{"codigo":"uniplus.selecao.banca.tipo_nao_admite_instancia_superior","requisitos":["UNI-REQ-0454","UNI-REQ-0478"],"oQueAconteceu":["O per\xedodo de recurso da fase ou da etapa declara que admite inst\xe2ncia superior,\\nmas a banca que avaliou o item recorrido \xe9 de um tipo que encerra o recurso na\\n1\xaa inst\xe2ncia (UNI-REQ-0478). Para esses tipos, o recurso \xe9 julgado em 1\xaa\\ninst\xe2ncia, por banca diferente da que avaliou, e a decis\xe3o \xe9 final no Uni+; o\\nsistema n\xe3o exige banca nem prazo de 2\xaa inst\xe2ncia nesse per\xedodo. Por isso o\\nedital n\xe3o pode declarar o contr\xe1rio.","A caracter\xedstica \\"encerra o recurso na 1\xaa inst\xe2ncia\\" \xe9 do cadastro do tipo e\\nfica registrada no processo quando a banca \xe9 criada. Mudar o cadastro depois n\xe3o\\naltera uma banca j\xe1 configurada. Se mais de uma banca avaliou o item e alguma\\ndelas tem a caracter\xedstica, o recurso \xe9 recusado.","A mensagem cita a fase pelo c\xf3digo, ou a etapa pela posi\xe7\xe3o, a banca pelo nome do\\ntipo e pelo n\xfamero dela, e o tipo de decis\xe3o do item. A recusa vem na\\npublica\xe7\xe3o e na retifica\xe7\xe3o em ato \xfanico, como o c\xf3digo desta p\xe1gina no corpo da\\nresposta, e n\xe3o na lista `errors[]`. O campo apontado \xe9\\n`fases[i].regraRecurso.admiteInstanciaSuperior` na fase e\\n`etapas[i].recursos[j].admiteInstanciaSuperior` na etapa."],"comoResolver":["Declare que o recurso n\xe3o admite inst\xe2ncia superior. Com isso, o per\xedodo n\xe3o\\nprecisa de banca de 2\xaa inst\xe2ncia nem de prazo de 2\xaa inst\xe2ncia.","Exemplo: o per\xedodo de recurso da heteroidentifica\xe7\xe3o do \\"PSR 2027\\" declara\\n\\"admite inst\xe2ncia superior\\" e \xe9 recusado. Com \\"n\xe3o admite inst\xe2ncia superior\\",\\na publica\xe7\xe3o \xe9 aceita, e a decis\xe3o da banca de 1\xaa inst\xe2ncia \xe9 final no Uni+.","O painel de conformidade aponta a pend\xeancia antes da publica\xe7\xe3o, no item\\n`cronograma_instancia_superior_admitida_pelo_tipo_de_banca`."],"ondeAparece":["- Publica\xe7\xe3o inicial do processo seletivo\\n- Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Banca"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);